import { writeFile } from 'node:fs/promises'
import {
  ASTRA_BUILDER_CATALOG_HASH,
  ASTRA_BUILDER_CATALOG_SIGNATURE,
  ASTRA_BUILDER_CATALOG_VERSION,
} from '../src/components/GalaxySocial/builder/astraBuilderRecipeCatalog.js'

const lines = [
  '// GENERATED by scripts/generate-astra-builder-server-catalog.mjs. Do not edit by hand.',
  'const ASTRA_BUILDER_ENCODING_V1 = "u16le-v1";',
  'const ASTRA_BUILDER_ENCODING_V2 = "u32le-v2";',
  `const ASTRA_BUILDER_CATALOG_VERSION = ${ASTRA_BUILDER_CATALOG_VERSION};`,
  `const ASTRA_BUILDER_CATALOG_HASH = "${ASTRA_BUILDER_CATALOG_HASH}";`,
  `const ASTRA_BUILDER_CATALOG_SIGNATURE = ${JSON.stringify(ASTRA_BUILDER_CATALOG_SIGNATURE, null, 2)};`,
  'const ASTRA_BUILDER_RECIPE_TRAITS = new Map(ASTRA_BUILDER_CATALOG_SIGNATURE.map(({ id, legacyBlockType, rotationSteps }) => [id, { legacyBlockType, rotationSteps }]));',
  'const ASTRA_BUILDER_ALLOWED_RECIPE_IDS = new Set(ASTRA_BUILDER_RECIPE_TRAITS.keys());',
  'module.exports = { ASTRA_BUILDER_CATALOG_VERSION, ASTRA_BUILDER_CATALOG_HASH, ASTRA_BUILDER_CATALOG_SIGNATURE, ASTRA_BUILDER_ENCODING_V1, ASTRA_BUILDER_ENCODING_V2, ASTRA_BUILDER_RECIPE_TRAITS, ASTRA_BUILDER_ALLOWED_RECIPE_IDS };',
  '',
]

await writeFile(new URL('../functions/astraBuilderRecipeCatalog.cjs', import.meta.url), lines.join('\n'))
console.log(`Astra Builder server catalog generated: ${ASTRA_BUILDER_CATALOG_HASH}`)
